<?php
$names=['cliente_nome'=>'Cliente','sede_nome'=>'Sede','titolo'=>'Titolo','numero'=>'Numero preventivo','stato'=>'Stato','modalita'=>'Modalità','infestante'=>'Infestante','area_interessata'=>'Area interessata','descrizione'=>'Descrizione','rilevazioni'=>'Rilievi','trattamenti_consigliati'=>'Trattamenti consigliati','prodotti'=>'Prodotti e materiali','precauzioni'=>'Precauzioni','costo_stimato'=>'Costo stimato','pianificato_il'=>'Data e ora','operatore_id'=>'Operatore incaricato','voci'=>'Servizi e voci di costo','imponibile'=>'Imponibile','iva'=>'IVA','sconto'=>'Sconto','validita_fino'=>'Valido fino al','note'=>'Note','tipo'=>'Tipo di evento','inizio'=>'Inizio','fine'=>'Fine','descrizione'=>'Descrizione'];
$hidden=['id','azienda_id','cliente_id','sede_id','richiesta_id','sopralluogo_id','creato_il','aggiornato_il','archiviato_at'];
$heading=$module==='sopralluoghi'?'Sopralluogo':($module==='preventivi'?'Preventivo':'Evento calendario');
?>
<div class="page-head"><div><a href="/app/<?= e($module) ?>" class="text-decoration-none">← Torna a <?= e($module) ?></a><p class="text-uppercase small fw-semibold text-success mt-3 mb-1"><?= e($heading) ?> · #<?= (int)$record['id'] ?></p><h1 class="h2 mb-0"><?= e($record['titolo']??$record['numero']??$heading) ?></h1></div><?php if($auth->can($module,'modifica')): ?><a class="btn btn-outline-primary" href="/app/<?= e($module) ?>/<?= (int)$record['id'] ?>/modifica">Modifica</a><?php endif ?></div>
<?php if($module==='sopralluoghi'&&($record['stato']??'')==='completato'&&$auth->can('preventivi','creazione')): ?><div class="alert alert-success d-flex flex-wrap justify-content-between align-items-center gap-2"><span>Sopralluogo completato: puoi usare i dati raccolti per preparare un’offerta.</span><a class="btn btn-success" href="/app/preventivi/nuovo?sopralluogo_id=<?= (int)$record['id'] ?>">Crea preventivo</a></div><?php endif ?>
<?php if($module==='preventivi'&&($record['stato']??'')==='accettato'&&$auth->can('contratti','creazione')): ?><div class="alert alert-success d-flex flex-wrap justify-content-between align-items-center gap-2"><span>Preventivo accettato: puoi trasformarlo in un contratto ricorrente.</span><a class="btn btn-success" href="/app/contratti/nuovo?preventivo_id=<?= (int)$record['id'] ?>">Crea contratto</a></div><?php endif ?>
<?php if($module==='preventivi'): $total=max(0,(float)($record['imponibile']??0)-(float)($record['sconto']??0))*(1+(float)($record['iva']??0)/100); ?><div class="row g-3 mb-3"><div class="col-sm-4"><div class="card border-0 shadow-sm"><div class="card-body"><small class="text-secondary">Imponibile</small><div class="h4 mb-0"><?= e(number_format((float)$record['imponibile'],2,',','.')) ?> €</div></div></div></div><div class="col-sm-4"><div class="card border-0 shadow-sm"><div class="card-body"><small class="text-secondary">Stato</small><div class="h4 mb-0"><?= e(ucfirst(str_replace('_',' ',$record['stato']))) ?></div></div></div></div><div class="col-sm-4"><div class="card border-0 shadow-sm"><div class="card-body"><small class="text-secondary">Totale indicativo IVA inclusa</small><div class="h4 mb-0 text-success"><?= e(number_format($total,2,',','.')) ?> €</div></div></div></div></div><?php endif ?>
<div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5 mb-3">Dettagli</h2><dl class="row mb-0"><?php if(isset($record['cliente_nome'])): ?><dt class="col-sm-3 text-secondary">Cliente</dt><dd class="col-sm-9"><?= e($record['cliente_nome']) ?></dd><?php endif ?><?php if(isset($record['sede_nome'])): ?><dt class="col-sm-3 text-secondary">Sede</dt><dd class="col-sm-9"><?= e($record['sede_nome']) ?></dd><?php endif ?><?php foreach($record as $key=>$value):if(in_array($key,$hidden,true)||in_array($key,['cliente_nome','sede_nome'],true)||$value===null||$value==='')continue;$label=$names[$key]??ucfirst(str_replace('_',' ',$key));if(in_array($key,['pianificato_il','inizio','fine'],true))$value=date('d/m/Y H:i',strtotime($value));elseif($key==='validita_fino')$value=date('d/m/Y',strtotime($value));elseif(in_array($key,['costo_stimato','imponibile','sconto'],true))$value=number_format((float)$value,2,',','.').' €';elseif($key==='iva')$value=$value.'%';elseif($key==='stato')$value=ucfirst(str_replace('_',' ',$value)); ?><dt class="col-sm-3 text-secondary"><?= e($label) ?></dt><dd class="col-sm-9"><?= nl2br(e((string)$value)) ?></dd><?php endforeach ?></dl></div></div>
